function OverseaManageOthersMainDialog:OnFocus(focus)
    if focus then
        CfUtils.SetTopCommonCb(function()
            GameUtils.ShowBlackOverlay(nil, function()
                local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
                local maidCoffeeHomeDojo = maidCoffeeComponent:GetMaidCoffeeHomeDoJo()
                maidCoffeeHomeDojo:SetIsOther(false)
                maidCoffeeHomeDojo:SaveCacheData(nil)
                ---@type MaidCoffeeConstants
                local MaidCoffeeConstants = import("Game.MaidCoffee.MaidCoffeeConstants")
                Events.Broadcast(MaidCoffeeConstants.EventNames.MaidCoffeeBackHome)
                UIModule.BackDialog()
            end)
        end)
    else
        CfUtils.ResetNavigatorCustomBackAction()
    end
end

function OverseaManageOthersMainDialog:OnShow()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.parameters = self.controller.Argument.parameters
        self.data = self.parameters.data
        self.isSuccess = false
        cs_coroutine.yield_return(self:RefreshShow(self.data))
        while not self.isSuccess do
            cs_coroutine.yield_return()
        end
        self.controller:SetExtraArgument(1)
    end))
    return coWait
end

function OverseaManageOthersMainDialog:RefreshShow(responseData)
    self.curData = responseData
    self.isApply = false
    CfUtils.SetUISwitchText(self.ApplyTxt,1)
    CfUtils.SetUISwitchImage(self.ApplyIcon,1)
    self:SetBtnTimes()
    CfUtils.FillText(self.TxtName,self.curData.name)
    CfUtils.FillText(self.TxtLv,string.format("<size=38><color=#dddddd>LV.</size></color>%s",self.curData.level))
    self:SetPlayerHeadNode()
    self:SetBtnApplyState()
    self:SetBusinessNode()

    local isRefresh = checkNumber(self.controller.Argument.extra) == 0
    if not isRefresh then
        self.isSuccess = true
        return
    end
    local MaidCoffeeConstants = import("Game.MaidCoffee.MaidCoffeeConstants")
    Events.Broadcast(MaidCoffeeConstants.EventNames.MaidCoffeeLoadOtherHome)
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    self.isSuccess = component:IsLoadOtherHomeSuccess()
    local time = os.time()
    while not self.isSuccess do
        cs_coroutine.yield_return()
        self.isSuccess = component:IsLoadOtherHomeSuccess()
        if (os.time() - time) > 3 then
            self.isSuccess = true
        end
    end
end

function OverseaManageOthersMainDialog:SetBtnTimes()
    local timesVo = CfUtils.GetCfVo(AutoIds.IdSetting3033, "MaidCoffeeManagerSettingVo", 56)
    local totalTimes = checkNumber(timesVo.num)
    local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local maidCoffeeHomeDojo = maidCoffeeComponent:GetMaidCoffeeHomeDoJo()
    maidCoffeeHomeDojo:UpdateRandomVisitedTimes(self.curData.randomVisitedTimes)
    maidCoffeeHomeDojo:SetIsOther(true)
    maidCoffeeHomeDojo:SaveCacheData(self.curData)
    local haveCallOnTimes = maidCoffeeHomeDojo:GetRandomVisitedTimes()
    CfUtils.FillText(self.TxtFrequency,string.format("<color=#FFFFFF>%s</color>/% s",math.max(0,totalTimes - haveCallOnTimes) ,totalTimes))
end

function OverseaManageOthersMainDialog:SetBtnApplyState()
    local isFriend = self.curData.isFriend == 1
    CfUtils.SetActive(self.BtnApplyFor.gameObject,not isFriend)
end

function OverseaManageOthersMainDialog:SetBusinessNode()
    local env = CfUtils.GetLuaScr(self.CellMerchant,BusinessNodePath)
    if env then
        env:RefreshShow(self.curData.darkMerchant)
    end
end

