function OverseaManageOthersMainDialog:OnBtnApplyForClick()
    if self.isApply then
        GameUtils.Toast(localize("已申请好友，请等待"))
        return
    end
    local friendComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.FriendComponent)
    friendComponent:AddFriend(self.curData.friendId, function ()
        self.isApply =true
        CfUtils.SetUISwitchText(self.ApplyTxt,2)
        CfUtils.SetUISwitchImage(self.ApplyIcon,2)
    end)
end

